

import { TextFieldEntry, SelectEntry, ListGroup, Group } from '@bpmn-io/properties-panel';
import { useService } from 'bpmn-js-properties-panel';

import { getProjectProcesses, getActiveProcessKey } from './processRegistry.js';

const ALLOWED_GROUPS = new Set([
  // Standard BPMN groups
  'general',                              // Name, ID
  'multiInstance',                         // Multi-instance (loop) configuration
  'timer',                                 // Timer event definitions
  'message',                               // Message event definitions
  'signal',                                // Signal event definitions
  'error',                                 // Error definitions
  'escalation',                            // Escalation definitions

  // Camunda groups relevant for translation
  'CamundaPlatform__CallActivity',         // Called element reference
  'CamundaPlatform__Condition',            // Sequence flow conditions (XOR gateway)
  'CamundaPlatform__Script',               // Script task content
]);

const SIGNAL_EXT_TYPES = new Set([
  'bpmn:IntermediateThrowEvent',
  'bpmn:IntermediateCatchEvent',
  'bpmn:StartEvent',
  'bpmn:EndEvent',
]);

function hasSignalDef(element) {
  var bo = element.businessObject || element;
  var eventDefs = bo.eventDefinitions || [];
  return eventDefs.some(function(def) { return def.$type === 'bpmn:SignalEventDefinition'; });
}

function hasMessageDef(element) {
  var bo = element.businessObject || element;
  var eventDefs = bo.eventDefinitions || [];
  return eventDefs.some(function(def) { return def.$type === 'bpmn:MessageEventDefinition'; });
}

function shouldShowExtensionProperties(element) {
  var type = element.type || (element.businessObject && element.businessObject.$type);
  return SIGNAL_EXT_TYPES.has(type) && hasSignalDef(element);
}

function isDataObject(element) {
  var type = element.type || (element.businessObject && element.businessObject.$type);
  return type === 'bpmn:DataObjectReference' && !hasDataInputExtension(element);
}

function hasDataInputExtension(element) {
  var bo = element.businessObject || element;
  var ext = bo.get('extensionElements');
  if (!ext || !ext.get('values')) return false;
  return ext.get('values').some(function(v) { return v.$type === 'b2x:DataInput'; });
}

function isDataInput(element) {
  var type = element.type || (element.businessObject && element.businessObject.$type);
  return type === 'bpmn:DataObjectReference' && hasDataInputExtension(element);
}

// Message catch events carry no payload here: the structure of the received
// message is defined by the data object linked to the event through a data
// association, so no editable entries are offered on the event itself.

function isMessageThrowEvent(element) {
  var type = element.type || (element.businessObject && element.businessObject.$type);
  return hasMessageDef(element)
      && (type === 'bpmn:IntermediateThrowEvent' || type === 'bpmn:EndEvent');
}

// ---- Data Object fields (b2x:Field) ----

function getB2xFields(businessObject) {
  var ext = businessObject.get('extensionElements');
  if (!ext) return [];
  return ext.get('values').filter(function(v) { return v.$type === 'b2x:Field'; });
}

function FieldNameEntry(props) {
  const { idPrefix, element, field } = props;
  const commandStack = useService('commandStack');
  const debounce = useService('debounceInput');
  return TextFieldEntry({
    element: field,
    id: idPrefix + '-name',
    label: 'Name',
    getValue: function() { return field.get('name') || ''; },
    setValue: function(value) {
      commandStack.execute('element.updateModdleProperties', {
        element: element,
        moddleElement: field,
        properties: { name: value }
      });
    },
    debounce: debounce
  });
}

function FieldValueEntry(props) {
  const { idPrefix, element, field } = props;
  const commandStack = useService('commandStack');
  const debounce = useService('debounceInput');
  return TextFieldEntry({
    element: field,
    id: idPrefix + '-value',
    label: 'Value',
    getValue: function() { return field.get('value') || ''; },
    setValue: function(value) {
      commandStack.execute('element.updateModdleProperties', {
        element: element,
        moddleElement: field,
        properties: { value: value || undefined }
      });
    },
    debounce: debounce
  });
}

/**
 * Types the backend understands: each one has a default the generated code can
 * start a value with (BPMNTranslator#defaultForType). Anything else — Object, a
 * class name, a typo — becomes an untyped variable holding null, which the
 * tuple never binds, so the list is closed on purpose.
 */
const SUPPORTED_FIELD_TYPES = ['Integer', 'Long', 'Double', 'Float', 'Boolean', 'String'];

/**
 * "Type" of a field, stored in `type` — the attribute the backend reads.
 *
 * Legacy fallback: until commit b91f381 the type box wrote to `value`, so
 * older diagrams keep the type in `value` and `type` empty. That value is read
 * back here and cleared when a type is picked, so it is not mistaken for an
 * initial value.
 */
function FieldTypeSelect(props) {
  const { idPrefix, element, field } = props;
  const commandStack = useService('commandStack');

  const current = field.get('type') || field.get('value') || '';

  const options = SUPPORTED_FIELD_TYPES.map(function(type) {
    return { label: type, value: type };
  });
  // a value stored before this entry became a list stays selectable and is
  // flagged, instead of silently disappearing from the panel
  if (current && SUPPORTED_FIELD_TYPES.indexOf(current) === -1) {
    options.unshift({ label: current + ' — not supported', value: current });
  }

  return SelectEntry({
    element: field,
    id: idPrefix + '-type',
    label: 'Type',
    getOptions: function() {
      return [{ label: 'Untyped', value: '' }].concat(options);
    },
    getValue: function() { return current; },
    setValue: function(value) {
      const properties = { type: value || undefined };
      // a legacy `value` holding a type name was the old type box, not an
      // initial value: clear it, otherwise the backend reads it as one
      if (SUPPORTED_FIELD_TYPES.indexOf(field.get('value')) !== -1) {
        properties.value = undefined;
      }
      commandStack.execute('element.updateModdleProperties', {
        element: element,
        moddleElement: field,
        properties: properties
      });
    }
  });
}

function dataObjectFieldEntries({ idPrefix, element, field }) {
  return [
    { id: idPrefix + '-name',  component: FieldNameEntry,       idPrefix, element, field },
    { id: idPrefix + '-type',  component: FieldTypeSelect,     idPrefix, element, field }
  ];
}

function dataInputFieldEntries({ idPrefix, element, field }) {
  return [
    { id: idPrefix + '-name',  component: FieldNameEntry,    idPrefix, element, field },
    { id: idPrefix + '-value', component: FieldValueEntry,   idPrefix, element, field },
    { id: idPrefix + '-type',  component: FieldTypeSelect,    idPrefix, element, field }
  ];
}

function addB2xField(element, bpmnFactory, commandStack) {
  const bo = element.businessObject;
  const commands = [];

  let ext = bo.get('extensionElements');
  if (!ext) {
    ext = bpmnFactory.create('bpmn:ExtensionElements', { values: [] });
    ext.$parent = bo;
    commands.push({
      cmd: 'element.updateModdleProperties',
      context: { element, moddleElement: bo, properties: { extensionElements: ext } }
    });
  }

  const field = bpmnFactory.create('b2x:Field', { name: '', type: '' });
  field.$parent = ext;
  commands.push({
    cmd: 'element.updateModdleProperties',
    context: {
      element,
      moddleElement: ext,
      properties: { values: [...ext.get('values'), field] }
    }
  });

  commandStack.execute('properties-panel.multi-command-executor', commands);
}

function removeB2xField(element, field, commandStack) {
  const ext = element.businessObject.get('extensionElements');
  if (!ext) return;
  const values = ext.get('values').filter(function(v) { return v !== field; });
  commandStack.execute('element.updateModdleProperties', {
    element, moddleElement: ext, properties: { values }
  });
}

function addFieldFactory({ element, bpmnFactory, commandStack }) {
  return function(event) {
    event.stopPropagation();
    addB2xField(element, bpmnFactory, commandStack);
  };
}

function removeFieldFactory({ element, field, commandStack }) {
  return function(event) {
    event.stopPropagation();
    removeB2xField(element, field, commandStack);
  };
}

function DataObjectFieldsGroup(element, injector, kind) {
  const bpmnFactory = injector.get('bpmnFactory');
  const commandStack = injector.get('commandStack');
  const fields = getB2xFields(element.businessObject);
  var entriesFn = kind === 'input' ? dataInputFieldEntries : dataObjectFieldEntries;

  const items = fields.map(function(field, index) {
    const id = element.id + '-b2xField-' + index;
    return {
      id,
      label: field.get('name') || '<unnamed field>',
      entries: entriesFn({ idPrefix: id, element, field }),
      autoFocusEntry: id + '-name',
      remove: removeFieldFactory({ element, field, commandStack })
    };
  });

  return {
    id: 'B2XKlaim__DataObjectFields',
    label: 'Extension properties',
    component: ListGroup,
    items,
    add: addFieldFactory({ element, bpmnFactory, commandStack })
  };
}


// Fields of the data object(s) linked to a message throw event through their
// data input associations. Per docs/translation.md the data object is the tuple
// passed in communication actions, so its fields are the only names that can be
// sent: this list is what the "Message Field" entry offers as a choice.
function getSourceDataObjectFields(element) {
  const bo = element.businessObject || element;
  const assocs = bo.get('dataInputAssociations') || [];
  const fields = [];
  assocs.forEach(function(assoc) {
    const sources = assoc.get('sourceRef') || [];
    (Array.isArray(sources) ? sources : [sources]).forEach(function(source) {
      if (source && typeof source === 'object') {
        fields.push.apply(fields, getB2xFields(source));
      }
    });
  });
  return fields;
}

// "Message Field": choose one of the source data object's fields instead of
// typing a name, so the selected name always exists in the tuple the throwing
// side reads. "All fields of the data object" (empty name) sends the whole tuple.
function ThrowPayloadFieldSelect(props) {
  const { idPrefix, element, field } = props;
  const commandStack = useService('commandStack');

  const sourceFields = getSourceDataObjectFields(element);
  const options = sourceFields.map(function(sourceField) {
    return {
      label: sourceField.get('name') || '<unnamed>',
      value: sourceField.get('name') || ''
    };
  });

  // A name stored before this entry became a list stays selectable and is
  // flagged, instead of silently disappearing from the panel.
  const current = field.get('name');
  if (current && !options.some(function(option) { return option.value === current; })) {
    options.unshift({ label: current + ' — not a field of the data object', value: current });
  }

  return SelectEntry({
    element: field,
    id: idPrefix + '-name',
    label: 'Message Field',
    getOptions: function() {
      return [{ label: 'All fields of the data object', value: '' }].concat(options);
    },
    getValue: function() { return field.get('name') || ''; },
    setValue: function(value) {
      commandStack.execute('element.updateModdleProperties', {
        element, moddleElement: field, properties: { name: value || undefined }
      });
    },
    disabled: sourceFields.length === 0,
    description: sourceFields.length === 0
      ? 'Link a data object to this event: its fields are the message.'
      : undefined
  });
}

function payloadEntries({ idPrefix, element, field }) {
  return [
    { id: idPrefix + '-name', component: ThrowPayloadFieldSelect, idPrefix, element, field }
  ];
}

function MessagePayloadGroup(element, injector) {
  const bpmnFactory = injector.get('bpmnFactory');
  const commandStack = injector.get('commandStack');
  const fields = getB2xFields(element.businessObject);

  const items = fields.map(function(field, index) {
    const id = element.id + '-b2xPayload-' + index;
    return {
      id,
      label: field.get('name') || '<unnamed>',
      entries: payloadEntries({ idPrefix: id, element, field }),
      autoFocusEntry: id + '-name',
      remove: removeFieldFactory({ element, field, commandStack })
    };
  });

  return {
    id: 'B2XKlaim__MessagePayload',
    label: 'Extension properties',
    component: ListGroup,
    items,
    add: addFieldFactory({ element, bpmnFactory, commandStack })
  };
}

// "Called element": the process a call activity starts. The translation emits
// it verbatim (eval(new <calledElement>(...))), so the value must be a process
// of the project: it is picked from the list instead of typed, because a typo
// used to produce a call to a process that does not exist.
function CalledElementSelect(props) {
  const { idPrefix, element } = props;
  const commandStack = useService('commandStack');
  const bo = element.businessObject || element;

  const activeKey = getActiveProcessKey();
  const processes = getProjectProcesses().filter(function(process) {
    // a process cannot call itself
    return process.key !== activeKey && process.id !== activeKey;
  });

  const options = processes.map(function(process) {
    return { label: process.name || process.key, value: process.key };
  });

  // A value stored before this entry became a list stays selectable and is
  // flagged, instead of silently disappearing from the panel.
  const current = bo.get('calledElement');
  if (current && !options.some(function(option) { return option.value === current; })) {
    options.unshift({ label: current + ' — not a process of this project', value: current });
  }

  return SelectEntry({
    element: element,
    id: idPrefix + '-calledElement',
    label: 'Called element',
    getOptions: function() { return options; },
    getValue: function() { return bo.get('calledElement') || ''; },
    setValue: function(value) {
      commandStack.execute('element.updateModdleProperties', {
        element: element,
        moddleElement: bo,
        properties: { calledElement: value || undefined }
      });
    },
    disabled: options.length === 0,
    description: options.length === 0
      ? 'Add another process to the project first: a call activity starts one of them.'
      : 'Process started by this activity; it must exist in the project.'
  });
}

function CallActivityGroup(element) {
  return {
    id: 'CamundaPlatform__CallActivity',
    label: 'Called element',
    component: Group,
    entries: [
      { id: 'calledElement', component: CalledElementSelect, idPrefix: element.id, element: element }
    ]
  };
}

// ---- Provider ----

export default function CustomPropertiesProvider(propertiesPanel, injector) {
  this._injector = injector;
  propertiesPanel.registerProvider(200, this);
}

CustomPropertiesProvider.$inject = ['propertiesPanel', 'injector'];

CustomPropertiesProvider.prototype.getGroups = function(element) {
  const injector = this._injector;
  return function(groups) {
    const showThrowPayload = isMessageThrowEvent(element);

    const filtered = groups
      .filter(function(group) {
        if (group.id === 'CamundaPlatform__ExtensionProperties') {
          return shouldShowExtensionProperties(element);
        }
        return ALLOWED_GROUPS.has(group.id);
      })
      .map(function(group) {
        // Replace the standard "Called element" text field by a choice among
        // the project's processes (same group id, our own single entry).
        if (group.id === 'CamundaPlatform__CallActivity' && element.type === 'bpmn:CallActivity') {
          return CallActivityGroup(element);
        }
        return group;
      });

    if (isDataObject(element)) {
      filtered.push(DataObjectFieldsGroup(element, injector, 'object'));
    } else if (isDataInput(element)) {
      filtered.push(DataObjectFieldsGroup(element, injector, 'input'));
    } else if (showThrowPayload) {
      filtered.push(MessagePayloadGroup(element, injector));
    }

    return filtered;
  };
};